/* eslint-disable react/prop-types */
import { styled, useTheme } from '@mui/material/styles';
import Box from '@mui/material/Box';
import MuiDrawer from '@mui/material/Drawer';
import MuiAppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import List from '@mui/material/List';
import CssBaseline from '@mui/material/CssBaseline';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import MenuIcon from '@mui/icons-material/Menu';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import ListItem from '@mui/material/ListItem';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import { Avatar, Menu, MenuItem, Tooltip } from '@mui/material';
import { Logout } from '@mui/icons-material';
// import PasswordSharpIcon from '@mui/icons-material/PasswordSharp';
import { useEffect, useState } from 'react';
import { getUser, logout } from '../@utilities/manager';
import { NavLink, useLocation, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { isLoading, loaded } from '../store/slice';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { blue } from '@mui/material/colors';

const drawerWidth = 240;

const openedMixin = (theme) => ({
    width: drawerWidth,
    transition: theme.transitions.create('width', {
        easing: theme.transitions.easing.sharp,
        duration: theme.transitions.duration.enteringScreen,
    }),
    overflowX: 'hidden',
});

const closedMixin = (theme) => ({
    transition: theme.transitions.create('width', {
        easing: theme.transitions.easing.sharp,
        duration: theme.transitions.duration.leavingScreen,
    }),
    overflowX: 'hidden',
    width: `calc(${theme.spacing(8)} + 10px)`,
    [theme.breakpoints.up('sm')]: {
        width: `calc(${theme.spacing(8)} + 10px)`,
    },
});

const DrawerHeader = styled('div')(({ theme }) => ({
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'flex-end',
    padding: theme.spacing(0, 1),
    // necessary for content to be below app bar
    ...theme.mixins.toolbar,
}));

const AppBar = styled(MuiAppBar, {
    shouldForwardProp: (prop) => prop !== 'open',
})(({ theme, open }) => ({
    zIndex: theme.zIndex.drawer + 1,
    transition: theme.transitions.create(['width', 'margin'], {
        easing: theme.transitions.easing.sharp,
        duration: theme.transitions.duration.leavingScreen,
    }),
    ...(open && {
        marginLeft: drawerWidth,
        width: `calc(100% - ${drawerWidth}px)`,
        transition: theme.transitions.create(['width', 'margin'], {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.enteringScreen,
        }),
    }),
}));

const Drawer = styled(MuiDrawer, { shouldForwardProp: (prop) => prop !== 'open' })(
    ({ theme, open }) => ({
        width: drawerWidth,
        flexShrink: 0,
        whiteSpace: 'nowrap',
        boxSizing: 'border-box',
        ...(open && {
            ...openedMixin(theme),
            '& .MuiDrawer-paper': openedMixin(theme),
        }),
        ...(!open && {
            ...closedMixin(theme),
            '& .MuiDrawer-paper': closedMixin(theme),
        }),
    }),
);

export const Sidebar = ({ rutas, children }) => {

    const theme = useTheme();
    const location = useLocation();
    const [open, setOpen] = useState(true);
    const [selectedIndex, setSelectedIndex] = useState('/');
    const [rutasSeleccionadas, setRutasSeleccionadas] = useState([]);
    const [rutaAnterior, setRutaAnterior] = useState({ nombre: '', ruta: '' });
    const [rutaActual, setRutaActual] = useState('');
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { loading } = useSelector((state) => state.loading);

    const [anchorEl, setAnchorEl] = useState(null);
    const open1 = Boolean(anchorEl);

    const handleClick = (event) => {
        setAnchorEl(event.currentTarget);
    };

    const handleClose = () => {
        setAnchorEl(null);

    };

    const handleDrawerOpen = () => {
        setOpen(true);
    };

    const handleDrawerClose = () => {
        setOpen(false);
    };

    const cerrar = () => {
        dispatch(loaded());
        logout(() => {
            navigate('/login');
        });
    }

    const logoutSystem = () => {
        dispatch(isLoading());
        // dispatch(resetPosition());
        setTimeout(cerrar, 2000);
    };

    const rutaRecursiva = (rutas, arreglo) => {
        let rutaAux = rutas;
        let nuevasRutas = rutas.find(item => item.llave === arreglo[0])?.subrutas;

        if (nuevasRutas && nuevasRutas.length > 0) {
            arreglo.shift();
            return rutaRecursiva(nuevasRutas, arreglo)
        } else {
            return {
                rutas: rutaAux,
                llave: arreglo[0]
            }
        }
    };

    const iniciales = () => {
        let datos = getUser();
        if (datos === null) {
            return 'CC'
        } else {
            let nombreInicial = datos.nombre.split(' ').map(palabra => palabra.charAt(0)).join('');
            let apellidoInicial = datos.apellido.split(' ').map(palabra => palabra.charAt(0)).join('');
            return nombreInicial.charAt(0) + apellidoInicial.charAt(0);
        }
    }

    useEffect(() => {
        let url = location.pathname;
        let url2 = location.pathname;
        let url3 = location.pathname;
        if (url === '/') {
            setRutasSeleccionadas(rutas);
            setSelectedIndex('/');

        } else {
            url = url.split('/');
            url.shift();
            setRutasSeleccionadas(rutaRecursiva(rutas, url).rutas);
            setSelectedIndex(rutaRecursiva(rutas, url).llave);
        }

        if (url2.split('/').length > 3) {
            url2 = url2.split('/');
            url2.shift();
            let rutaAnterior = rutas.find(item => item.llave === url2[0]);
            setRutaAnterior({ nombre: rutaAnterior.nombre, ruta: rutaAnterior.ruta });
        } else {
            setRutaAnterior({ nombre: 'Menú principal', ruta: '/' });
        }

        if (url3.split('/').length > 2) {
            url3 = url3.split('/');
            setRutaActual(url3[url3.length - 2]);
        } else {
            setRutaActual('');
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [location.pathname])

    return (
        <Box sx={{ display: 'flex' }}>
            <CssBaseline />
            <div className={`${loading ? 'z-10' : 'p-0 m-0'}`}>
                <AppBar position="fixed" open={open}>
                    <Toolbar className='bg-blue-900 flex justify-between'>
                        <div className='flex flex-wrap'>
                            <div className='self-center hidden sm:block'>
                                <IconButton
                                    color="inherit"
                                    aria-label="open drawer"
                                    onClick={handleDrawerOpen}
                                    edge="start"
                                    sx={{
                                        marginRight: 5,
                                        ...(open && { display: 'none' }),
                                    }}
                                >
                                    <MenuIcon />
                                </IconButton>
                            </div>
                            {
                                open ? null :
                                    <div className="site-logo">

                                        <img
                                            className="w-24"
                                            src="data:image/png;base64,"
                                            alt="#"
                                        />
                                    </div>
                            }
                        </div>

                        {/* AJUSTES DE LA CUENTA DEL USUARIO */}
                        <Tooltip title="Ajustes">
                            <IconButton
                                onClick={handleClick}
                                size="small"
                                sx={{ ml: 2 }}
                                aria-controls={open1 ? 'account-menu' : undefined}
                                aria-haspopup="true"
                                aria-expanded={open1 ? 'true' : undefined}
                            >

                                <Avatar sx={{ width: 40, height: 40, bgcolor: blue[500] }}>
                                    {iniciales()}
                                </Avatar>
                            </IconButton>
                        </Tooltip>
                        <Menu
                            anchorEl={anchorEl}
                            id="account-menu"
                            open={open1}
                            onClose={handleClose}
                            onClick={handleClose}
                            PaperProps={{
                                elevation: 0,
                                sx: {
                                    overflow: 'visible',
                                    filter: 'drop-shadow(0px 2px 8px rgba(0,0,0,0.32))',
                                    mt: 1.5,
                                    '& .MuiAvatar-root': {
                                        width: 32,
                                        height: 32,
                                        ml: -0.5,
                                        mr: 1,
                                    },
                                    '&::before': {
                                        content: '""',
                                        display: 'block',
                                        position: 'absolute',
                                        top: 0,
                                        right: 14,
                                        width: 10,
                                        height: 10,
                                        bgcolor: 'background.paper',
                                        transform: 'translateY(-50%) rotate(45deg)',
                                        zIndex: 0,
                                    },
                                },
                            }}
                            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
                            anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
                        >
                            {/* <MenuItem onClick={() => console.log('cambio de contrase;a')}>
                                <ListItemIcon>
                                    <PasswordSharpIcon fontSize="small" />
                                </ListItemIcon>
                                Cambiar contraseña
                            </MenuItem> */}
                            <MenuItem onClick={logoutSystem}>
                                <ListItemIcon>
                                    <Logout fontSize="small" />
                                </ListItemIcon>
                                Cerrar sesión
                            </MenuItem>
                        </Menu>
                        {/* FIN AJUSTES DE LA CUENTA DE USUARIO */}

                    </Toolbar>
                </AppBar>

                <Drawer variant="permanent" open={open}>
                    <DrawerHeader>
                        <div className="site-logo hidden sm:block">
                            <a href="/">
                                <img
                                    height={100}
                                    width={100}
                                    className="cursor-pointer"
                                    src="data:image/png;base64,"
                                    alt="#"
                                />
                            </a>
                        </div>
                        <IconButton onClick={handleDrawerClose}>
                            {theme.direction === 'rtl' ? <ChevronRightIcon /> : <ChevronLeftIcon />}
                        </IconButton>
                    </DrawerHeader>
                    <Divider />

                    <div className='flex justify-center'>
                        <Avatar src="/broken-image.jpg" sx={{ width: 70, height: 70, marginTop: 2, backgroundColor: 'rgba(0, 0, 0, 0.34)' }} />
                    </div>

                    {
                        open ?
                            <div className='flex flex-wrap justify-center'>
                                <p className='w-full flex justify-center mt-1 text-xs font-bold text-gray-500'>

                                    {
                                        getUser() ?
                                            `${getUser().nombre.split(' ')[0].toUpperCase()} ${getUser().apellido.split(' ')[0].toUpperCase()}`
                                            : null
                                    }
                                </p>
                                <p className='text-xs font-bold text-gray-500'>
                                    {
                                        getUser() ?
                                            getUser().acceso.toUpperCase()
                                            : null
                                    }
                                </p>
                            </div>
                            : null
                    }

                    {
                        location.pathname !== '/' && location.pathname.split('/').length > 2 ?
                            <List>
                                <ListItem key={1} disablePadding sx={{ display: 'block' }}>
                                    <NavLink
                                        key={1}
                                        to={rutaAnterior.ruta}
                                    >
                                        <ListItemButton
                                            sx={{
                                                minHeight: 48,
                                                justifyContent: 'center',
                                                px: 2.5,
                                                backgroundColor: 'inherit',
                                            }}
                                        >
                                            <ListItemIcon
                                                sx={{
                                                    minWidth: 0,
                                                    mr: open ? 3 : 'auto',
                                                    justifyContent: 'center',
                                                }}>
                                                <ArrowBackIcon />
                                                {
                                                    open ?
                                                        <div className='ml-3'>
                                                            {rutaAnterior.nombre}
                                                        </div>
                                                        : null
                                                }
                                            </ListItemIcon>
                                        </ListItemButton>
                                    </NavLink>
                                </ListItem>
                            </List>
                            : null
                    }

                    <List sx={{ marginTop: open && location.pathname !== '/' && location.pathname.split('/').length > 2 ? 0 : 3 }}>
                        {
                            open && location.pathname !== '/' && location.pathname.split('/').length > 2 ?
                                <div className='flex justify-start mx-5 mb-2 text-gray-400 font-bold text-xs'>
                                    {rutaActual.toUpperCase()}
                                </div>
                                : null
                        }
                        {rutasSeleccionadas.map((item) => (
                            <Tooltip key={item.nombre} placement="right" title={!open ? item.nombre : ''}>
                                <ListItem key={item.nombre} disablePadding sx={{ display: 'block' }}>
                                    <NavLink
                                        key={item.nombre}
                                        to={item.ruta}
                                    >
                                        <ListItemButton
                                            sx={{
                                                minHeight: 48,
                                                justifyContent: open ? 'initial' : 'center',
                                                px: 2.5,
                                                backgroundColor: selectedIndex === item.llave ? '#1e3a8a' : 'inherit',
                                                ":hover": {
                                                    backgroundColor: selectedIndex === item.llave ? '#1e3a8a' : '',
                                                }
                                            }}
                                        // selected={selectedIndex === 0}
                                        // onClick={(event) => handleListItemClick(event, item.llave, item.nombre)}
                                        >
                                            <ListItemIcon
                                                sx={{
                                                    minWidth: 0,
                                                    mr: open ? 3 : 'auto',
                                                    justifyContent: 'center',
                                                    color: selectedIndex === item.llave ? '#ffffff' : ''
                                                }}
                                            >
                                                {item.icono}
                                            </ListItemIcon>
                                            <ListItemText primary={item.nombre} sx={{ opacity: open ? 1 : 0, color: selectedIndex === item.llave ? '#ffffff' : '' }} />
                                        </ListItemButton>
                                    </NavLink>
                                </ListItem>
                            </Tooltip>
                        ))}
                    </List>

                    {/* <Divider />
                    <List>
                        {['All mail', 'Trash', 'Spam'].map((text, index) => (
                            <ListItem key={text} disablePadding sx={{ display: 'block' }}>
                                <ListItemButton
                                    sx={{
                                        minHeight: 48,
                                        justifyContent: open ? 'initial' : 'center',
                                        px: 2.5,
                                    }}
                                >
                                    <ListItemIcon
                                        sx={{
                                            minWidth: 0,
                                            mr: open ? 3 : 'auto',
                                            justifyContent: 'center',
                                        }}
                                    >
                                        {index % 2 === 0 ? <InboxIcon /> : <MailIcon />}
                                    </ListItemIcon>
                                    <ListItemText primary={text} sx={{ opacity: open ? 1 : 0 }} />
                                </ListItemButton>
                            </ListItem>
                        ))}
                    </List> */}

                </Drawer>
            </div>
            <Box component="main" sx={{ flexGrow: 1, p: 3 }}>
                <DrawerHeader />
                {children}
            </Box>
        </Box>

    );
}